/* Sistec Soluções - browser bundle, generated by build-static.mjs */
"use strict";
(() => {
const DISCOUNT_PERCENT = 30;
const MAX_CENTS = 9_999_999_999;

/** Parses Brazilian currency without silently discarding invalid characters. */
function parseCurrency(value) {
  if (typeof value !== 'string') return { valid: false, reason: 'format' };
  const raw = value.trim().replace(/^R\$\s*/i, '').replace(/[\s\u00a0]/g, '');
  if (!raw) return { valid: false, reason: 'empty' };
  let normalized;
  if (/^(?:\d{1,3}(?:\.\d{3})+|\d+)(?:,\d{1,2})?$/.test(raw)) {
    normalized = raw.replace(/\./g, '').replace(',', '.');
  } else if (/^\d+\.\d{1,2}$/.test(raw)) {
    normalized = raw;
  } else return { valid: false, reason: 'format' };
  const [whole, fractional = ''] = normalized.split('.');
  const cents = Number(whole) * 100 + Number(fractional.padEnd(2, '0'));
  if (!Number.isSafeInteger(cents) || cents > MAX_CENTS) return { valid: false, reason: 'large' };
  if (cents <= 0) return { valid: false, reason: 'positive' };
  return { valid: true, cents };
}

/** All calculations use integer cents; savings + the new bill equals the original. */
function calculateSavings(currentCents) {
  if (!Number.isSafeInteger(currentCents) || currentCents <= 0 || currentCents > MAX_CENTS) {
    throw new RangeError('Informe um valor positivo em centavos dentro do limite.');
  }
  const monthlySavingsCents = Math.round(currentCents * DISCOUNT_PERCENT / 100);
  const newBillCents = currentCents - monthlySavingsCents;
  return {
    currentCents,
    discountPercent: DISCOUNT_PERCENT,
    monthlySavingsCents,
    newBillCents,
    sixMonthSavingsCents: monthlySavingsCents * 6,
    yearlySavingsCents: monthlySavingsCents * 12,
    yearlyCurrentCents: currentCents * 12,
    yearlyNewBillCents: newBillCents * 12
  };
}

const currency = new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' });
const editable = new Intl.NumberFormat('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const formatCurrency = cents => currency.format(cents / 100);
const formatInput = cents => editable.format(cents / 100);

function createSummary(result) {
  return [
    'SISTEC SOLUÇÕES',
    'Simulação de economia na conta de energia',
    '',
    `Conta mensal atual: ${formatCurrency(result.currentCents)}`,
    `Desconto simulado: ${result.discountPercent}%`,
    `Valor mensal com desconto: ${formatCurrency(result.newBillCents)}`,
    `Economia mensal: ${formatCurrency(result.monthlySavingsCents)}`,
    `Economia em 6 meses: ${formatCurrency(result.sixMonthSavingsCents)}`,
    `Economia em 12 meses: ${formatCurrency(result.yearlySavingsCents)}`,
    '',
    'Simulação de 30% sobre o valor informado, com arredondamento em centavos.',
    'A projeção considera o mesmo valor de conta durante os 12 meses.',
    'Mais economia. Mais possibilidades.'
  ].join('\n');
}


/** Generates the actual downloadable PDF, shared by the website and verification. */
async function createSavingsPDF(result, { pdfLib = globalThis.PDFLib, logoBytes, now = new Date() } = {}) {
  if (!pdfLib) throw new Error('A biblioteca de PDF não foi carregada.');
  if (!result || !Number.isSafeInteger(result.currentCents) || result.currentCents <= 0) throw new Error('Simulação inválida.');
  const { PDFDocument, StandardFonts, rgb } = pdfLib;
  const doc = await PDFDocument.create();
  doc.setTitle('Sistec Soluções - Simulação de economia');
  doc.setAuthor('Sistec Soluções');
  doc.setSubject('Desconto de 30% na conta de energia e projeções de economia');
  doc.setCreator('Simulador Sistec Soluções');
  doc.setCreationDate(now);
  doc.setModificationDate(now);
  doc.setLanguage('pt-BR');
  const page = doc.addPage([595.28, 841.89]);
  const font = await doc.embedFont(StandardFonts.Helvetica);
  const bold = await doc.embedFont(StandardFonts.HelveticaBold);
  const color = hex => rgb(parseInt(hex.slice(1, 3), 16) / 255, parseInt(hex.slice(3, 5), 16) / 255, parseInt(hex.slice(5, 7), 16) / 255);
  const palette = {
    navy: color('#093665'), blue: color('#0872dc'), green: color('#138446'),
    yellow: color('#ffdb50'), ink: color('#16354f'), muted: color('#536e86'),
    pale: color('#f0f6fc'), mint: color('#edf8ef'), border: color('#d9e6f2'), white: rgb(1, 1, 1)
  };
  const money = cents => formatCurrency(cents).replace(/\u00a0/g, ' ');
  function text(value, x, y, size = 10, ink = palette.ink, weight = font, maxWidth = null) {
    let fit = size;
    if (maxWidth) while (weight.widthOfTextAtSize(value, fit) > maxWidth && fit > 7) fit -= .5;
    page.drawText(value, { x, y, size: fit, color: ink, font: weight });
  }
  function right(value, endX, y, size = 10, ink = palette.ink, weight = font, maxWidth = null) {
    let fit = size;
    if (maxWidth) while (weight.widthOfTextAtSize(value, fit) > maxWidth && fit > 7) fit -= .5;
    text(value, endX - weight.widthOfTextAtSize(value, fit), y, fit, ink, weight);
  }
  const rect = (x, y, width, height, fill, border) => page.drawRectangle({ x, y, width, height, color: fill, ...(border ? { borderColor: border, borderWidth: .8 } : {}) });
  const line = (x1, y1, x2, y2, ink = palette.border, thickness = .8) => page.drawLine({ start: { x: x1, y: y1 }, end: { x: x2, y: y2 }, color: ink, thickness });
  function paragraph(value, x, y, width, size = 8.5, ink = palette.muted, leading = 13) {
    const words = value.split(' ');
    let current = '';
    let cursor = y;
    for (const word of words) {
      const trial = current ? `${current} ${word}` : word;
      if (font.widthOfTextAtSize(trial, size) > width && current) {
        text(current, x, cursor, size, ink);
        cursor -= leading;
        current = word;
      } else current = trial;
    }
    if (current) text(current, x, cursor, size, ink);
    return cursor;
  }

  rect(0, 830, 595.28, 12, palette.blue);
  rect(462, 830, 90, 12, palette.yellow);
  rect(552, 830, 43.28, 12, palette.green);
  if (logoBytes) {
    const logo = await doc.embedPng(logoBytes);
    const width = 203;
    const height = width * logo.height / logo.width;
    page.drawImage(logo, { x: 38, y: 741, width, height });
  } else {
    text('SISTEC SOLUÇÕES', 42, 770, 23, palette.navy, bold);
  }
  right('SIMULAÇÃO DE ECONOMIA', 553, 785, 8, palette.blue, bold);
  const date = new Intl.DateTimeFormat('pt-BR', { timeZone: 'America/Sao_Paulo', dateStyle: 'short' }).format(now);
  right(`Emitido em ${date}`, 553, 768, 8.5, palette.muted);
  line(42, 717, 553, 717);

  text('Sua conta de energia,', 42, 679, 28, palette.navy, bold);
  text('30% mais leve.', 42, 645, 28, palette.blue, bold);
  rect(444, 642, 109, 61, palette.navy);
  text('DESCONTO', 459, 682, 8, palette.white, bold);
  text('30%', 458, 654, 29, palette.yellow, bold);
  text('Mais economia. Mais possibilidades.', 42, 617, 10.5, palette.muted);

  rect(42, 490, 190, 101, palette.pale, palette.border);
  text('SUA CONTA ATUAL', 58, 570, 8, palette.muted, bold);
  text(money(result.currentCents), 58, 537, 29, palette.navy, bold, 158);
  text('Valor mensal informado', 58, 511, 8, palette.muted);
  rect(246, 490, 307, 101, palette.navy);
  text('COM A SISTEC SOLUÇÕES', 264, 570, 8, palette.white, bold);
  text(money(result.newBillCents), 264, 536, 34, palette.yellow, bold, 270);
  text('Valor mensal com 30% de desconto', 264, 511, 8, palette.white);

  rect(42, 387, 248, 84, palette.white, palette.border);
  text('ECONOMIA POR MÊS', 58, 447, 8, palette.muted, bold);
  text(money(result.monthlySavingsCents), 58, 413, 30, palette.green, bold, 215);
  rect(305, 387, 248, 84, palette.mint);
  text('ECONOMIA EM 12 MESES', 321, 447, 8, palette.green, bold);
  text(money(result.yearlySavingsCents), 321, 413, 30, palette.green, bold, 215);

  text('Sua economia ao longo do tempo', 42, 357, 15, palette.navy, bold);
  rect(42, 319, 511, 26, palette.pale);
  text('PERÍODO', 54, 328, 7.5, palette.muted, bold);
  right('CONTA ATUAL', 268, 328, 7.5, palette.muted, bold);
  right('COM A SISTEC', 410, 328, 7.5, palette.muted, bold);
  right('ECONOMIA', 541, 328, 7.5, palette.green, bold);
  const rows = [
    [1, '1 mês', 298], [6, '6 meses', 264], [12, '12 meses', 230]
  ];
  for (const [months, label, y] of rows) {
    if (months === 12) rect(42, y - 12, 511, 32, palette.mint);
    text(label, 54, y, 9, palette.ink, months === 12 ? bold : font);
    right(money(result.currentCents * months), 268, y, 10, palette.muted, font, 139);
    right(money(result.newBillCents * months), 410, y, 10, palette.navy, font, 134);
    right(money(result.monthlySavingsCents * months), 541, y, 10, palette.green, bold, 119);
    if (months !== 12) line(42, y - 13, 553, y - 13);
  }
  text('Valores acumulados para cada período, mantendo a mesma conta mensal.', 42, 199, 8, palette.muted);

  rect(42, 104, 511, 75, palette.pale);
  rect(42, 104, 3, 75, palette.blue);
  text('Como esta simulação foi calculada', 57, 158, 9, palette.navy, bold);
  paragraph('Aplicamos 30% de desconto sobre o valor informado. A economia é arredondada em centavos e o valor com desconto é a diferença entre a conta atual e essa economia.', 57, 141, 480);
  paragraph('A projeção considera o mesmo valor da conta durante 12 meses. Se o valor mudar, a economia em reais também muda.', 57, 116, 480, 8, palette.muted, 11);

  text('Sistec Soluções', 42, 70, 11, palette.navy, bold);
  text('Mais economia. Mais possibilidades.', 42, 54, 8, palette.muted);
  right('1 / 1', 553, 54, 8, palette.muted);
  return doc.save();
}

const embeddedLogoBase64 = "";

const byId = id => document.getElementById(id);
const form = byId('calculator-form');
const input = byId('valor-conta');
const field = byId('money-field');
const error = byId('input-error');
const exampleButtons = [...document.querySelectorAll('[data-amount]')];
const resultWrap = byId('result-wrap');
const insightPanel = byId('insight-panel');
const copyButton = byId('copy-summary');
const downloadButton = byId('download-summary');
let activeResult = null;
let announcementTimer;
let copyBusy = false;
let pdfBusy = false;
let cachedLogoBytes;

const errorMessage = reason => ({
  empty: 'Informe o valor da sua conta para calcular.',
  positive: 'Informe um valor maior que zero.',
  large: `Informe um valor de até ${formatCurrency(MAX_CENTS)}.`,
  format: 'Digite um valor válido, como 500,00 ou 1.500,50.'
}[reason]);

function setError(message = '') {
  error.textContent = message;
  error.hidden = !message;
  field.classList.toggle('is-invalid', !!message);
  input.setAttribute('aria-invalid', String(!!message));
}

function setMoney(id, cents) {
  const element = byId(id);
  const value = cents === null ? '—' : formatCurrency(cents);
  element.textContent = value;
  element.classList.toggle('long-value', value.length > 14);
}

function announce(result) {
  clearTimeout(announcementTimer);
  announcementTimer = setTimeout(() => {
    byId('live-result').textContent = result
      ? `Conta com desconto: ${formatCurrency(result.newBillCents)} por mês. Economia mensal de ${formatCurrency(result.monthlySavingsCents)} e economia anual de ${formatCurrency(result.yearlySavingsCents)}.`
      : 'Informe um valor válido para ver sua simulação.';
  }, 350);
}

function updateChart(result) {
  const hasSavings = result && result.yearlySavingsCents > 0;
  // Zero savings from rounding on very small bills is displayed as a flat line.
  const endY = hasSavings ? 24 : 163;
  const points = [0, 1, 4, 7, 10, 12].map(month => {
    const x = 10 + month * 40;
    const y = hasSavings ? 163 - (month / 12) * 139 : 163;
    return `${x} ${y.toFixed(2)}`;
  });
  const line = `M${points.join(' L')}`;
  byId('chart-line').setAttribute('d', line);
  byId('chart-area').setAttribute('d', `${line} L490 163 L10 163 Z`);
  byId('chart-end').setAttribute('cy', String(endY));
  byId('chart-description').textContent = result
    ? `Com uma economia mensal de ${formatCurrency(result.monthlySavingsCents)}, você acumula ${formatCurrency(result.yearlySavingsCents)} em 12 meses, considerando o mesmo valor de conta. Em 6 meses, a economia é de ${formatCurrency(result.sixMonthSavingsCents)}.`
    : 'Informe o valor da conta no simulador para ver a projeção.';
}

function render(result, { example = false, announceChange = true } = {}) {
  activeResult = result;
  const valid = !!result;
  const moneyValues = {
    'new-bill': result?.newBillCents,
    'monthly-saving': result?.monthlySavingsCents,
    'yearly-saving': result?.yearlySavingsCents,
    'annual-highlight': result?.yearlySavingsCents,
    'compare-current': result?.currentCents,
    'compare-new': result?.newBillCents,
    'milestone-one': result?.monthlySavingsCents,
    'milestone-six': result?.sixMonthSavingsCents,
    'milestone-twelve': result?.yearlySavingsCents
  };
  for (const [id, cents] of Object.entries(moneyValues)) setMoney(id, cents ?? null);
  resultWrap.classList.toggle('is-empty', !valid);
  insightPanel.classList.toggle('is-empty', !valid);
  copyButton.disabled = !valid || copyBusy;
  downloadButton.disabled = !valid || pdfBusy;
  byId('result-caption').textContent = valid
    ? `${example ? 'Exemplo' : 'Sua simulação'} com uma conta de ${formatCurrency(result.currentCents)}`
    : 'Informe o valor da conta para ver sua economia';
  byId('annual-context').textContent = valid
    ? `Considerando uma conta mensal de ${formatCurrency(result.currentCents)}.`
    : 'Informe um valor no simulador para ver sua projeção.';
  byId('action-status').textContent = '';
  for (const button of exampleButtons) button.setAttribute('aria-pressed', String(valid && Number(button.dataset.amount) === result.currentCents));
  updateChart(result);
  if (announceChange) announce(result);
}

function calculate({ showError = false, format = false, example = false, announceChange = true } = {}) {
  const parsed = parseCurrency(input.value);
  if (!parsed.valid) {
    setError(showError ? errorMessage(parsed.reason) : '');
    render(null, { announceChange });
    return false;
  }
  setError();
  if (format) input.value = formatInput(parsed.cents);
  render(calculateSavings(parsed.cents), { example, announceChange });
  return true;
}

input.addEventListener('input', () => calculate());
input.addEventListener('blur', () => calculate({ showError: true, format: true, announceChange: false }));
form.addEventListener('submit', event => {
  event.preventDefault();
  const valid = calculate({ showError: true, format: true });
  if (!valid) input.focus();
});
for (const button of exampleButtons) button.addEventListener('click', () => {
  input.value = formatInput(Number(button.dataset.amount));
  calculate({ example: true });
});

function showCopyDialog(text) {
  const dialog = byId('copy-dialog');
  const summary = byId('summary-text');
  summary.value = text;
  dialog.showModal();
  summary.focus();
  summary.select();
}

async function copySummary() {
  if (!activeResult || copyBusy) return;
  const text = createSummary(activeResult);
  copyBusy = true;
  copyButton.disabled = true;
  let copied = false;
  try {
    if (navigator.clipboard?.writeText) {
      await navigator.clipboard.writeText(text);
      copied = true;
    }
  } catch { /* Fall back to a selectable summary on restricted browsers. */ }
  if (!copied) {
    const temporary = document.createElement('textarea');
    temporary.value = text;
    temporary.style.position = 'fixed';
    temporary.style.top = '0';
    temporary.style.left = '-9999px';
    temporary.setAttribute('aria-label', 'Resumo da simulação para copiar');
    document.body.append(temporary);
    temporary.select();
    try { copied = !!document.execCommand?.('copy'); } catch { copied = false; }
    temporary.remove();
  }
  copyBusy = false;
  copyButton.disabled = !activeResult;
  if (copied) {
    byId('action-status').textContent = 'Simulação copiada. Pronta para compartilhar!';
    copyButton.focus({ preventScroll: true });
  } else {
    byId('action-status').textContent = 'Seu resumo está pronto para copiar.';
    showCopyDialog(text);
  }
}

copyButton.addEventListener('click', copySummary);
byId('select-summary').addEventListener('click', () => { byId('summary-text').focus(); byId('summary-text').select(); });
function getLogoBytes() {
  if (!cachedLogoBytes) {
    if (typeof embeddedLogoBase64 !== 'string') throw new Error('A logo não está disponível.');
    cachedLogoBytes = Uint8Array.from(atob(embeddedLogoBase64), char => char.charCodeAt(0));
  }
  return cachedLogoBytes;
}

async function downloadPDF() {
  if (!activeResult || pdfBusy) return;
  const requestedResult = { ...activeResult };
  pdfBusy = true;
  downloadButton.disabled = true;
  byId('pdf-button-label').textContent = 'Gerando PDF...';
  byId('action-status').textContent = 'Preparando seu resumo em PDF.';
  try {
    const bytes = await createSavingsPDF(requestedResult, { logoBytes: getLogoBytes() });
    const blob = new Blob([bytes], { type: 'application/pdf' });
    const url = URL.createObjectURL(blob);
    const anchor = document.createElement('a');
    anchor.href = url;
    anchor.download = 'simulacao-sistec-solucoes.pdf';
    document.body.append(anchor);
    anchor.click();
    anchor.remove();
    setTimeout(() => URL.revokeObjectURL(url), 30000);
    byId('action-status').textContent = 'PDF pronto para compartilhar!';
  } catch {
    byId('action-status').textContent = 'Não foi possível gerar o PDF. Recarregue a página e tente novamente.';
  } finally {
    pdfBusy = false;
    downloadButton.disabled = !activeResult;
    byId('pdf-button-label').textContent = 'Baixar resumo em PDF';
  }
}
downloadButton.addEventListener('click', downloadPDF);

byId('current-year').textContent = String(new Date().getFullYear());
calculate({ example: true, announceChange: false });

})();